package com.labresource.platform.sharing.repository;
import com.labresource.platform.sharing.entity.SharingRequest; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import jakarta.persistence.LockModeType; import java.time.LocalDateTime; import java.util.List; import java.util.Optional;
public interface SharingRequestRepository extends JpaRepository<SharingRequest,Long>{ @Query("select count(r)>0 from SharingRequest r where r.equipmentId=:equipment and r.status in ('PENDING','FORWARDED') and r.startDate < :end and r.endDate > :start") boolean hasOpenOverlap(@Param("equipment")Long equipment,@Param("start")LocalDateTime start,@Param("end")LocalDateTime end); List<SharingRequest> findByRequesterIdOrderByCreatedAtDesc(Long id); List<SharingRequest> findByRequesterInstitutionIdAndStatusOrderByCreatedAtDesc(Long id,String status); List<SharingRequest> findByEquipmentIdAndStatusOrderByCreatedAtDesc(Long id,String status); Page<SharingRequest> findByRequesterIdOrderByCreatedAtDesc(Long id,Pageable pageable); Page<SharingRequest> findByRequesterInstitutionIdAndStatusOrderByCreatedAtDesc(Long id,String status,Pageable pageable); Page<SharingRequest> findByStatusOrderByCreatedAtDesc(String status,Pageable pageable); @Query(value="select r from SharingRequest r, Equipment e where e.id=r.equipmentId and e.institutionId=:institution and r.status='FORWARDED'",countQuery="select count(r) from SharingRequest r, Equipment e where e.id=r.equipmentId and e.institutionId=:institution and r.status='FORWARDED'") Page<SharingRequest> ownerQueue(@Param("institution")Long institution,Pageable pageable); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select r from SharingRequest r where r.id=:id") Optional<SharingRequest> findByIdForUpdate(@Param("id")Long id); }
